import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.ModLoadingContext;

public final class ForgeAquamiraeClient {
    public static void init() {
        AquamiraeClient.init();
        ForgeAquamiraeClient.registerConfigScreen();
        MinecraftForge.EVENT_BUS.register(ForgeAquamiraeClient.class);
    }

    @SubscribeEvent
    public static void onCustomizeBossEventOverlay(CustomizeGuiOverlayEvent.BossEventProgress event) {
        BossHealthOverlayHandler.customizeOverlay(event.getBossEvent(), event.getGuiGraphics(), event.getX(), event.getY());
    }

    private static void registerConfigScreen() {
        ModLoadingContext.get().registerExtensionPoint(ConfigScreenHandler.ConfigScreenFactory.class, () -> new ConfigScreenHandler.ConfigScreenFactory((client, parent) -> ConfigScreenBuilder.create(parent)));
    }
}

