import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.client.event.RenderGuiOverlayEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;

public final class ArsNouveauCompat {
    private ArsNouveauCompat() {
    }

    @SubscribeEvent
    public static void onRenderOverlay(RenderGuiOverlayEvent.Pre event) {
        HotbarType currentType = HudConfig.getHotbarType();
        if (!HudConfig.shouldHideNativeManaOverlayForSource(currentType, ManaSource.ARS_NOUVEAU, HudState.isShowingMana, HudState.isShowingVampirismBlood)) {
            return;
        }
        if (ArsNouveauCompat.isArsManaOverlay(event.getOverlay().id())) {
            event.setCanceled(true);
        }
    }

    public static boolean shouldShowManaBar(Player player) {
        if (!(player instanceof LocalPlayer)) {
            return false;
        }
        try {
            Class<?> hudClass = Class.forName("com.hollingsworth.arsnouveau.client.gui.GuiManaHUD", false, ArsNouveauCompat.class.getClassLoader());
            Method method = hudClass.getMethod("shouldDisplayBar", new Class[0]);
            return Boolean.TRUE.equals(method.invoke(null, new Object[0]));
        }
        catch (LinkageError | ReflectiveOperationException ignored) {
            return false;
        }
    }

    public static AresHudCompatManager.ManaDataResult getManaData(Player player) {
        try {
            Class<?> manaUtilClass = Class.forName("com.hollingsworth.arsnouveau.api.util.ManaUtil", false, ArsNouveauCompat.class.getClassLoader());
            Method currentMethod = manaUtilClass.getMethod("getCurrentMana", LivingEntity.class);
            Method maxMethod = manaUtilClass.getMethod("getMaxMana", Player.class);
            int currentMana = (int)Math.max(0.0, ((Number)currentMethod.invoke(null, player)).doubleValue());
            int maxMana = Math.max(0, ((Number)maxMethod.invoke(null, player)).intValue());
            float percentage = maxMana > 0 ? (float)currentMana / (float)maxMana : 0.0f;
            return new AresHudCompatManager.ManaDataResult(currentMana, maxMana, percentage);
        }
        catch (LinkageError | ReflectiveOperationException ignored) {
            return new AresHudCompatManager.ManaDataResult(0, 0, 0.0f);
        }
    }

